from beanie import Document, before_event, after_event, Insert, Save, Replace, Delete, Validate
class User(Document):
name: str
@before_event(Insert)
async def normalise(self):
self.name = self.name.strip()
@after_event(Save, Replace)
async def publish_event(self):
await publish({"type": "user.saved", "id": str(self.id)})
Events: Insert, Replace, Update, Delete, Save, Validate. Multiple events per decorator. Async or sync function bodies.

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
class UserCreate(BaseModel):
name: str
email: EmailStr
class UserOut(BaseModel):
id: str
name: str
email: str
@classmethod
def from_doc(cls, u: User):
return cls(id=str(u.id), name=u.name, email=u.email)
app = FastAPI(lifespan=lifespan)
@app.post("/users", response_model=UserOut, status_code=201)
async def create_user(input: UserCreate):
u = User(**input.model_dump())
await u.insert()
return UserOut.from_doc(u)
@app.get("/users/{user_id}", response_model=UserOut)
async def get_user(user_id: str):
u = await User.get(PydanticObjectId(user_id))
if not u:
raise HTTPException(404)
return UserOut.from_doc(u)
Separation of concerns:
UserCreate — request body.
User (Beanie) — database document.
UserOut — response body (no internal fields).
Helps avoid leaking server-side fields (__v, internal_flag, etc.) into responses.

from fastapi import Depends
class UserRepo:
async def by_email(self, email: str):
return await User.find_one(User.email == email.lower())
def repo() -> UserRepo:
return UserRepo()
@app.get("/by-email/{email}")
async def by_email(email: str, repo: UserRepo = Depends(repo)):
return await repo.by_email(email)
Useful when you want to mock the repository in tests.
